const D = { energy: .5, scale: 1, density: .55, speed: 1, spin: .5, haze: .5, hue: 210, x: .4, y: .72, style: 'dusk', act: 'steady', seed: 0, alpha: 1 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const hw = h => ((h % 360) + 360) % 360;
const ho = P.hue - 210;
const L3 = (a, b, f) => [a[0] + (b[0]-a[0])*f, a[1] + (b[1]-a[1])*f, a[2] + (b[2]-a[2])*f];
const sh = c => [hw(c[0] + ho), c[1], c[2]];
const NR = 4;                                    // ridge ranks, 0 = farthest

const STY = {
  // overcast dusk: cool grey ridges, pale turbines silhouetted, muted
  dusk:      { skT:[214,26,48], skB:[206,14,78], ridge:[210,20,26], ridgeL:[200,18,44],
               tower:[210,8,86], blade:[210,6,90], glow:[8,60,80], grain:18, lineOnly:0 },
  // warm gold-hour: dark turbines against amber sky
  goldhour:  { skT:[28,36,44], skB:[42,58,88], ridge:[24,40,20], ridgeL:[34,44,34],
               tower:[26,20,26], blade:[24,18,22], glow:[16,70,80], grain:20, lineOnly:0 },
  // night nocturne: blue-dark, soft red aviation lights, faint moonlit blades
  nocturne:  { skT:[232,50,10], skB:[218,34,26], ridge:[224,34,8], ridgeL:[212,26,20],
               tower:[212,16,40], blade:[210,14,50], glow:[2,80,86], grain:12, lineOnly:0 },
  // ABSTRACTED cyan blueprint: turbines as line diagrams, rotor circles
  blueprint: { skT:[210,72,14], skB:[202,58,24], ridge:[198,40,26], ridgeL:[190,30,44],
               tower:[188,26,88], blade:[186,24,94], glow:[190,40,90], grain:5, lineOnly:1 },
  // ABSTRACTED sumi ink: silhouette ridges + turbines in tonal wash
  ink:       { skT:[30,5,90], skB:[30,3,82], ridge:[30,8,22], ridgeL:[30,6,40],
               tower:[30,7,26], blade:[30,6,30], glow:[30,10,50], grain:28, lineOnly:0 }
};
const st = STY[P.style] || STY.dusk;

const en = Math.max(0, Math.min(1, P.energy));
const hz = Math.max(0, Math.min(1, P.haze));
const key = width + 'x' + height + '|' + P.style + '|' + P.seed + '|' + Math.round(P.hue) + '|' + P.scale.toFixed(2) + '|' + P.density.toFixed(2) + '|' + P.y.toFixed(3);

if (!S.sky || S.key !== key) {
  const W = Math.max(2, Math.ceil(width)), H = Math.max(2, Math.ceil(height));
  const mk = (w, h) => { const g = createGraphics(Math.max(2, Math.ceil(w)), Math.max(2, Math.ceil(h))); g.colorMode(g.HSB, 360, 100, 100, 100); return g; };
  if (S.sky) { S.sky.remove(); S.ridges.forEach(r => r.g.remove()); S.cloud.remove(); }
  S.sky = mk(W, H); S.cloud = mk(W, H);

  const g = S.sky; g.noStroke();
  const cT = sh(st.skT), cB = sh(st.skB);
  for (let yy = 0; yy < H; yy++) { const c = L3(cT, cB, Math.pow(yy / H, .75)); g.fill(c[0], c[1], c[2]); g.rect(0, yy, W, 1); }

  const ridgeC = sh(st.ridge), ridgeL = sh(st.ridgeL), skB = sh(st.skB);
  const baseY = height * P.y;

  // --- ridge ranks + the turbines that stand on each crest ---
  S.ridges = []; S.turb = [];
  for (let L = 0; L < NR; L++) {
    const near = L / (NR - 1);
    const haze = (1 - near) * (.55 + .4 * hz);
    const q = mk(W, H); q.noStroke();
    const crestBase = baseY - u * (.2 - near * .26);   // farther ranks sit higher (toward horizon)
    const amp = u * (.03 + near * .06) * P.scale;
    const rC = L3(ridgeC, skB, haze);
    const crest = xx => crestBase + Math.sin(xx * .0026 + fr(L * 5 + 1) * 6.3) * amp
                        + Math.sin(xx * .0061 + fr(L * 5 + 2) * 6.3) * amp * .5
                        + Math.sin(xx * .013) * amp * .2;
    q.fill(rC[0], rC[1], rC[2], 100);
    q.beginShape(); q.vertex(-10, H);
    for (let xx = -10; xx <= W + 10; xx += u * .02) q.vertex(xx, crest(xx));
    q.vertex(W + 10, H); q.endShape(q.CLOSE);
    // faint hillshade texture on the near ranks
    if (!st.lineOnly && near > .3) {
      q.strokeWeight(Math.max(.5, u * .0012));
      for (let s = 0; s < Math.floor(6 * near); s++) {
        const yy0 = crestBase + s / 6 * u * .12;
        q.stroke(ridgeL[0], ridgeL[1], Math.max(2, ridgeL[2] - haze * 20), 20);
        q.beginShape(); q.noFill();
        for (let xx = -10; xx <= W + 10; xx += u * .04) q.vertex(xx, crest(xx) + s / 6 * u * .12 + Math.sin(xx * .01) * u * .004);
        q.endShape();
      }
      q.noStroke();
    }
    // aerial veil
    q.fill(skB[0], skB[1] * .8, skB[2], haze * 50); q.rect(0, 0, W, H);
    S.ridges.push({ g: q, near: near });
    // place turbines along this crest
    const nt = Math.floor((2 + near * 3) + P.density * (2 + near * 4));
    const rr = u * (.05 + near * .09) * P.scale;       // rotor radius grows with nearness
    for (let i = 0; i < nt; i++) {
      const tx = ((i + .5) / nt + (fr(L * 20 + i) - .5) * .5 / nt) * W;
      S.turb.push({ L: L, near: near, x: tx, y: crest(tx), r: rr, phase: fr(L * 20 + i + 7) * 6.283, haze: haze,
                    towerH: rr * (1.4 + fr(L * 20 + i + 9) * .4), rate: (1 + L * .43 + fr(i + L) * .25) });
    }
    // (turbines drawn back-to-front live each frame using S.turb order)
  }

  // drifting cloud band
  const clC = L3(sh(st.skB), sh(st.skT), .3);
  S.cloud.noStroke();
  for (let i = 0; i < 9; i++) {
    const bx = fr(i * 5 + 41) * W, by = u * (.04 + fr(i * 5 + 42) * .45);
    const bw = u * (.5 + fr(i * 5 + 43) * 1.1), bhh = u * (.04 + fr(i * 5 + 44) * .09);
    for (let rep = -1; rep <= 1; rep++) for (let kk = 0; kk < 4; kk++) {
      S.cloud.fill(clC[0], clC[1] * (1 - kk * .12), Math.min(99, clC[2] + kk * 4), 8 * (1 - kk * .2));
      S.cloud.ellipse(bx + rep * W, by + kk * bhh * .1, bw * (1 - kk * .1), bhh * (1 - kk * .08));
    }
  }
  S.key = key;
}

// ---------------- act ----------------
const sec = ((Math.floor(K.section) % 6) + 6) % 6;
const ACT = { steady: 1, gust: 1.3 + .5 * Math.sin(K.t * .11 + sec), becalm: .35 + .25 * Math.sin(K.t * .07) };
const wind = Math.max(.15, ACT[P.act] != null ? ACT[P.act] : 1);
const spinRate = (.5 + P.spin * 1.6) * P.speed * wind + A.lowmid * .3;

noStroke();
image(S.sky, 0, 0);
const CW = S.cloud.width;
const cx = ((-K.t * u * .005 * P.speed % CW) + CW) % CW;
push(); tint(0, 0, 100, 70); image(S.cloud, cx - CW, 0); image(S.cloud, cx, 0); pop();

// draw ranks + their turbines, farthest first
const towerC = sh(st.tower), bladeC = sh(st.blade), glowC = sh(st.glow);
const drift = 0.9 * Math.sin(K.t * .17) + 0.5 * Math.sin(K.t * .43 + 1.7) + 0.3 * Math.sin(K.t * .89);
for (let L = 0; L < NR; L++) {
  const r = S.ridges[L];
  const dx = drift * u * .0016 * (.3 + r.near);
  image(r.g, dx, 0);
  // turbines of this rank
  const alpha = 100 - r.haze * 55;
  for (const t of S.turb) {
    if (t.L !== L) continue;
    const nx = t.x + dx, ny = t.y;
    const hubY = ny - t.towerH;
    // tower
    strokeWeight(Math.max(.8, t.r * .05));
    stroke(towerC[0], towerC[1], Math.max(2, towerC[2] - r.haze * 24), alpha);
    line(nx, ny, nx, hubY);
    noStroke();
    // rotor
    const theta = t.phase + K.t * spinRate * t.rate;
    push(); translate(nx, hubY); rotate(theta);
    for (let b = 0; b < 3; b++) {
      rotate(6.2832 / 3);
      if (st.lineOnly) {
        stroke(bladeC[0], bladeC[1], bladeC[2], alpha); strokeWeight(Math.max(1, t.r * .04)); noFill();
        line(0, 0, 0, -t.r);
      } else {
        fill(bladeC[0], bladeC[1], Math.max(2, bladeC[2] - r.haze * 20), alpha);
        beginShape();
        vertex(-t.r * .02, 0); vertex(-t.r * .012, -t.r); vertex(t.r * .006, -t.r); vertex(t.r * .03, 0);
        endShape(CLOSE);
      }
    }
    pop();
    if (st.lineOnly) { noFill(); stroke(bladeC[0], bladeC[1], bladeC[2], alpha * .5); strokeWeight(1); ellipse(nx, hubY, t.r * 2, t.r * 2); noStroke(); }
    // nacelle
    fill(towerC[0], towerC[1], Math.max(2, towerC[2] - r.haze * 20), alpha);
    ellipse(nx, hubY, t.r * .14, t.r * .1);
    // soft slow aviation glow (never a hard blink)
    if (r.near > .4) {
      const gl = .5 + .5 * Math.sin(K.t * 1.6 + t.phase);
      blendMode(ADD);
      fill(glowC[0], glowC[1], glowC[2], (6 + 14 * gl) * en);
      ellipse(nx, hubY, t.r * (.3 + gl * .25), t.r * (.3 + gl * .25));
      blendMode(BLEND);
    }
  }
}

// grain, vignette, alpha
if (st.grain > 6) {
  const ng = Math.floor(st.grain * 5);
  for (let i = 0; i < ng; i++) {
    const gx = ((fr(i * 3 + 201) * width) + Math.sin(K.t * .01 + i) * u * .002 + width) % width;
    const gy = fr(i * 3 + 202) * height;
    fill(st.skB[0], st.skB[1] * .4, fr(i * 3 + 203) > .5 ? 90 : 8, 3 + fr(i) * 5);
    rect(gx, gy, u * .0016, u * .0016);
  }
}
for (let i = 0; i < 5; i++) {
  noFill(); strokeWeight(u * .05);
  stroke(sh(st.ridge)[0], st.ridge[1], 6, 16 * (1 - i * .17));
  rect(-u * .03 + i * u * .03, -u * .03 + i * u * .03, width + u * .06 - i * u * .06, height + u * .06 - i * u * .06);
}
noStroke();
if (P.alpha < 1) { fill(sh(st.ridge)[0], st.ridge[1] * .5, 5, (1 - P.alpha) * 100); rect(0, 0, width, height); }
blendMode(BLEND);
drawingContext.shadowBlur = 0;
